use crate::source::{CompileError, Span};

#[derive(Clone, Debug, PartialEq)]
pub enum TokenKind { Ident(String), Int(i64), Float(f64), Str(String), Newline, Eof, Let, Set, As, Gives, To, End, If, Then, Else, Repeat, From, While, For, Each, In, Break, Continue, Give, Back, Say, Ask, True, False, And, Or, Not, Class, Extends, New, Is, Try, Catch, Fail, Use, Extern, Function, Plus, Minus, Star, Slash, Eq, Lt, Gt, LParen, RParen, LBracket, RBracket, LBrace, RBrace, Comma, Dot, Colon, Semi, Percent, NotEq, LtEq, GtEq }
#[derive(Clone, Debug)] pub struct Token { pub kind: TokenKind, pub span: Span }

pub fn lex(src:&str)->Result<Vec<Token>,CompileError>{
 let bytes=src.as_bytes();let mut i=0;let mut line=1;let mut col=1;let mut out=Vec::new();
 macro_rules! push {($kind:expr,$start:expr,$sl:expr,$sc:expr)=>{out.push(Token{kind:$kind,span:Span{start:$start,end:i,line:$sl,column:$sc}});};}
 while i<bytes.len(){let c=bytes[i] as char;if c==' '||c=='\t'||c=='\r'{i+=1;col+=1;continue}if c=='\n'{push!(TokenKind::Newline,i,line,col);i+=1;line+=1;col=1;continue}if c=='#'{while i<bytes.len()&&bytes[i] as char!='\n'{i+=1;col+=1}continue}let start=i;let sl=line;let sc=col;match c{
 '"'=>{i+=1;col+=1;let mut s:Vec<u8>=Vec::new();while i<bytes.len()&&bytes[i]!=b'"'{if bytes[i]==b'\\'{i+=1;col+=1;if i>=bytes.len(){break}s.push(match bytes[i]{b'n'=>b'\n',b't'=>b'\t',b'"'=>b'"',b'\\'=>b'\\',x=>x})}else{if bytes[i]==b'\n'{line+=1;col=0}s.push(bytes[i])}i+=1;col+=1}if i>=bytes.len(){return Err(CompileError::new(Span{start,end:i,line:sl,column:sc},"unterminated string"))}i+=1;col+=1;push!(TokenKind::Str(String::from_utf8_lossy(&s).into_owned()),start,sl,sc)}
 '0'..='9'=>{let mut j=i;while j<bytes.len()&&(bytes[j] as char).is_ascii_digit(){j+=1}let mut kind=match src[i..j].parse::<i64>(){Ok(n)=>TokenKind::Int(n),Err(_)=>return Err(CompileError::new(Span{start,end:j,line:sl,column:sc},"integer literal is too large"))};if j<bytes.len()&&bytes[j] as char=='.'&&j+1<bytes.len()&&(bytes[j+1] as char).is_ascii_digit(){j+=1;while j<bytes.len()&&(bytes[j] as char).is_ascii_digit(){j+=1}kind=TokenKind::Float(src[i..j].parse().unwrap())}col+=j-i;i=j;push!(kind,start,sl,sc)}
 'A'..='Z'|'a'..='z'|'_'=>{let mut j=i+1;while j<bytes.len()&&((bytes[j] as char).is_ascii_alphanumeric()||bytes[j] as char=='_'){j+=1}let w=&src[i..j];let kind=match w.to_ascii_uppercase().as_str(){"LET"=>TokenKind::Let,"SET"=>TokenKind::Set,"AS"=>TokenKind::As,"GIVES"=>TokenKind::Gives,"TO"=>TokenKind::To,"END"=>TokenKind::End,"IF"=>TokenKind::If,"THEN"=>TokenKind::Then,"ELSE"=>TokenKind::Else,"REPEAT"=>TokenKind::Repeat,"FROM"=>TokenKind::From,"WHILE"=>TokenKind::While,"FOR"=>TokenKind::For,"EACH"=>TokenKind::Each,"IN"=>TokenKind::In,"BREAK"=>TokenKind::Break,"CONTINUE"=>TokenKind::Continue,"GIVE"=>TokenKind::Give,"BACK"=>TokenKind::Back,"SAY"=>TokenKind::Say,"ASK"=>TokenKind::Ask,"TRUE"=>TokenKind::True,"FALSE"=>TokenKind::False,"AND"=>TokenKind::And,"OR"=>TokenKind::Or,"NOT"=>TokenKind::Not,"CLASS"=>TokenKind::Class,"EXTENDS"=>TokenKind::Extends,"NEW"=>TokenKind::New,"IS"=>TokenKind::Is,"TRY"=>TokenKind::Try,"CATCH"=>TokenKind::Catch,"FAIL"=>TokenKind::Fail,"USE"=>TokenKind::Use,"EXTERN"=>TokenKind::Extern,"FUNCTION"=>TokenKind::Function,_=>TokenKind::Ident(w.to_string())};col+=j-i;i=j;push!(kind,start,sl,sc)}
 '+'=>{i+=1;col+=1;push!(TokenKind::Plus,start,sl,sc)}'-'=>{i+=1;col+=1;push!(TokenKind::Minus,start,sl,sc)}'*'=>{i+=1;col+=1;push!(TokenKind::Star,start,sl,sc)}'/'=>{i+=1;col+=1;push!(TokenKind::Slash,start,sl,sc)}'='=>{i+=1;col+=1;push!(TokenKind::Eq,start,sl,sc)}'<'=>{if i+1<bytes.len()&&bytes[i+1] as char=='='{i+=2;col+=2;push!(TokenKind::LtEq,start,sl,sc)}else{i+=1;col+=1;push!(TokenKind::Lt,start,sl,sc)}}'>'=>{if i+1<bytes.len()&&bytes[i+1] as char=='='{i+=2;col+=2;push!(TokenKind::GtEq,start,sl,sc)}else{i+=1;col+=1;push!(TokenKind::Gt,start,sl,sc)}}'!'=>{if i+1<bytes.len()&&bytes[i+1] as char=='='{i+=2;col+=2;push!(TokenKind::NotEq,start,sl,sc)}else{return Err(CompileError::new(Span{start,end:i+1,line:sl,column:sc},"unexpected `!`; use NOT or !="))}}
 '('=>{i+=1;col+=1;push!(TokenKind::LParen,start,sl,sc)}')'=>{i+=1;col+=1;push!(TokenKind::RParen,start,sl,sc)}'['=>{i+=1;col+=1;push!(TokenKind::LBracket,start,sl,sc)}']'=>{i+=1;col+=1;push!(TokenKind::RBracket,start,sl,sc)}'{'=>{i+=1;col+=1;push!(TokenKind::LBrace,start,sl,sc)}'}'=>{i+=1;col+=1;push!(TokenKind::RBrace,start,sl,sc)}'%' => {i+=1;col+=1;push!(TokenKind::Percent,start,sl,sc)}','=>{i+=1;col+=1;push!(TokenKind::Comma,start,sl,sc)}'.'=>{i+=1;col+=1;push!(TokenKind::Dot,start,sl,sc)}':'=>{i+=1;col+=1;push!(TokenKind::Colon,start,sl,sc)}';'=>{i+=1;col+=1;push!(TokenKind::Semi,start,sl,sc)}
 _=>return Err(CompileError::new(Span{start,end:i+1,line:sl,column:sc},format!("unexpected character `{}`",src[i..].chars().next().unwrap_or(c))))}}
 out.push(Token{kind:TokenKind::Eof,span:Span{start:i,end:i,line,column:col}});Ok(out)
}
